#!/usr/bin/env python3
"""Bootstrap attenuation simulation: proves Likert blindspot is measurement attenuation, not power gap."""

import json
import os
import sys
from pathlib import Path

import numpy as np


def load_jsonl(path):
    """Load JSONL file, return list of dicts."""
    records = []
    with open(path, "r") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def cohens_d_paired(diffs):
    """Cohen's d (paired) = mean(diffs) / std(diffs, ddof=1). Returns 0.0 if std==0."""
    if len(diffs) < 2:
        return 0.0
    s = np.std(diffs, ddof=1)
    if s == 0.0:
        return 0.0
    return np.mean(diffs) / s


def find_first_existing(base_dir, candidates):
    """Return the first existing file path from candidates, or None."""
    for rel in candidates:
        p = base_dir / rel
        if p.exists():
            return p
    return None


def extract_diffs(records):
    """Filter NLI-pass records and compute score diffs. Returns (diffs_array, n_total, n_nli_pass, n_with_likert)."""
    n_total = len(records)
    nli_pass = [r for r in records if r.get("passed_cf") is True]
    n_nli_pass = len(nli_pass)
    # Keep only records that have both Likert scores
    valid = []
    for r in nli_pass:
        so = r.get("score_original")
        sc = r.get("score_counterfactual")
        if so is not None and sc is not None:
            try:
                valid.append(float(sc) - float(so))
            except (ValueError, TypeError):
                pass
    return np.array(valid, dtype=np.float64), n_total, n_nli_pass, len(valid)


def bootstrap_curve(diffs, rng, n_bootstrap=10000):
    """Run bootstrap attenuation simulation across subsample sizes."""
    n = len(diffs)
    if n == 0:
        return []

    # Choose subsample sizes based on dataset size
    if n >= 200:
        ns = [s for s in [50, 100, 150, 200, 250, 300] if s <= n]
        if n not in ns:
            ns.append(n)
    else:
        ns = [s for s in [30, 50, 70] if s <= n]
        if n not in ns:
            ns.append(n)

    curve = []
    for n_sub in ns:
        ds = np.empty(n_bootstrap, dtype=np.float64)
        for b in range(n_bootstrap):
            sample = rng.choice(diffs, size=n_sub, replace=True)
            ds[b] = cohens_d_paired(sample)
        curve.append({
            "n": int(n_sub),
            "d_median": float(np.median(ds)),
            "d_ci_lo": float(np.percentile(ds, 2.5)),
            "d_ci_hi": float(np.percentile(ds, 97.5)),
            "n_bootstrap": n_bootstrap,
        })
    return curve


def main():
    # Parse CLI arg for base directory
    if len(sys.argv) > 1:
        base_dir = Path(sys.argv[1])
    else:
        base_dir = Path("/root/causal_style_decomp_judge")

    n_bootstrap = 10000
    seed = 42
    rng = np.random.default_rng(seed)

    # Define axis × judge combinations and their candidate file paths
    combos = {
        "formality_qwen32b": [
            "data/verified_32b.jsonl",
            "data/scored_qwen32b_formality.jsonl",
            "data/scored_32b.jsonl",
        ],
        "verbosity_qwen32b": [
            "data/scored_qwen32b_verbosity.jsonl",
            "data/verified_verbosity.jsonl",
        ],
        "formality_gpt4o": [
            "data/scored_gpt4o_formality.jsonl",
        ],
        "verbosity_gpt4o": [
            "data/scored_gpt4o_verbosity.jsonl",
        ],
    }

    discovery = {}
    results = {}

    for combo_name, candidates in combos.items():
        filepath = find_first_existing(base_dir, candidates)
        if filepath is None:
            print(f"[SKIP] {combo_name}: no data file found among {candidates}", file=sys.stderr)
            continue

        rel_path = str(filepath.relative_to(base_dir))
        print(f"[LOAD] {combo_name}: {rel_path}", file=sys.stderr)

        try:
            records = load_jsonl(filepath)
        except Exception as e:
            print(f"[ERROR] {combo_name}: failed to load {rel_path}: {e}", file=sys.stderr)
            continue

        diffs, n_total, n_nli_pass, n_with_likert = extract_diffs(records)

        if len(diffs) == 0:
            print(f"[SKIP] {combo_name}: no valid NLI-pass pairs with Likert scores", file=sys.stderr)
            continue

        full_d = cohens_d_paired(diffs)

        discovery[combo_name] = {
            "file": rel_path,
            "n_total": n_total,
            "n_nli_pass": n_nli_pass,
            "n_with_likert": n_with_likert,
            "full_d": round(full_d, 6),
        }

        curve = bootstrap_curve(diffs, rng, n_bootstrap=n_bootstrap)

        results[combo_name] = {
            "file": rel_path,
            "n_total": n_with_likert,
            "full_d": round(full_d, 6),
            "curve": curve,
        }

        print(f"  n_with_likert={n_with_likert}, full_d={full_d:.4f}, curve_points={len(curve)}", file=sys.stderr)

    output = {
        "seed": seed,
        "n_bootstrap": n_bootstrap,
        "discovery": discovery,
        "results": results,
    }

    # Write to data/bootstrap_attenuation.json
    out_path = base_dir / "data" / "bootstrap_attenuation.json"
    os.makedirs(out_path.parent, exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\n[SAVED] {out_path}", file=sys.stderr)

    # Also print to stdout
    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

